INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 594, 1, "今日の運勢は小吉！　いろんな事件が起こる一日になりそう！　　状況をよく観察してみようじゃないか！　まさに探偵のごとくね！", 0, "", 0, 2, 60005, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 595, 1, "今日の運勢は小吉！　難しい頼み事をされるかもしれません！　　うまくやれればきっと成長につながります、挑戦してみましょう！", 0, "", 0, 2, 60005, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 596, 2, "今日の運勢は小吉！　空を眺めると気持ちが晴れやかに！　　　　眺めるだけじゃなくて、ひとっ飛びしちゃいましょうかっ♪", 0, "", 0, 2, 60005, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 597, 2, "今日の運勢は小吉！　掃除をすると運勢が開けそう！　　　　　　「わ、めんど」「ヴルムっ！　新年早々サボっちゃダメなんだからね！」", 0, "", 0, 2, 60005, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 598, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 190804, "カリン", 0, 3, 60005, 2);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 599, 0, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 190804, "カリン", 7, 3, 60005, 3);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 600, 1, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 190804, "カリン", 0, 1, 60006, 1);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, "", 601, 2, "今日の運勢は姫吉！　勇気を持って、新しいことに挑戦しよう！\n幸先がいいねえ少年！　今年もいい一年になるよう祈ってるよ。", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, "", 602, 2, "今日の運勢は姫吉！　どんなピンチも簡単に乗り越えられそう！\nよい結果が出たようで何よりです。さて、待人の方は……ふふ。", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, "", 603, 2, "今日の運勢は姫吉！　あの人と仲直り……できちゃうかも！？\nはあ……この私があなたの運勢に興味を抱くわけないでしょう？", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, "", 604, 1, "今日の運勢は大吉！　身近な友達との絆が深まる予感……？\n騎士様は、どなたと友誼を結ぶのでしょう？　気になります……", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, "", 605, 2, "今日の運勢は大吉！　ラッキーアイテムは「蛇の抜け殻」！\nこのアタシにお目にかかれるなんて……アンタ、幸せものね♪", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, "", 606, 2, "今日の運勢は中吉！　気になるあの人に会えちゃうかも！？\n『初夢を正夢にする枕』であなたに会え……な、なんでもない！", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, "", 607, 2, "今日の運勢は中吉！　子供に戻って、一日中遊びつくそう！\nお年玉でけん玉ゲット！　おじちゃん、もしかめ一万回やって！", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, "", 608, 1, "今日の運勢は中吉！　今日はおうちで、ゆーっくりくつろごう。\nお雑煮よし。みかんよし。さ、こたつで寝正月だ。君も入る？", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 609, 2, "今日の運勢は小吉！　突然のドッキリに注意！\nおや、後ろに髪の長い女の霊が──フフ、冗談です。私ですよ。", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 610, 2, "今日の運勢は小吉。慌てなくても、幸運はきっとやってくる。\n運は自分で掴むもの──媛が言ってました。でも、どうやって？", 0, "", 0, 2, 60006, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 611, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 190804, "カリン", 0, 3, 60006, 2);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 612, 0, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 190804, "カリン", 5, 3, 60006, 3);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 613, 1, "新年を迎え、新たに始まる一日を\nおみくじで占ってみませんか？\n良い運勢であるほど、\n沢山のプレゼントが貰えますよ♪", 190804, "カリン", 0, 1, 60007, 1);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, "", 614, 2, "今日の運勢は姫吉！　絶好調で最高の一日になりそう♪\nわたしも、騎士クンが一緒ならいつだって最高に幸せな日だよ……", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, "", 615, 2, "今日の運勢は姫吉！　新しいことに挑戦するチャンス！\nお姉さんも一緒に挑戦しちゃおっかな♪　飲み処の新規開拓とか！", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 1, "", 616, 2, "今日の運勢は姫吉！　日々の努力が実を結ぶ予感！\n今日一日鍛錬に勤しむべき、ということだな。では早速行こうか。", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, "", 617, 2, "今日の運勢は大吉！　家族サービスにはぴったりの日！\nさっそく弟くんにあまあまお姉ちゃんの出血大サービス、だよっ♪", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 2, "", 618, 2, "今日の運勢は大吉！　笑顔で過ごせば周りもみんなハッピーかも！\n『笑う顔はフグになる』ですねっ。幸せいっぱいお届けしますっ", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, "", 619, 2, "今日の運勢は中吉！　恋愛運良し、積極的な行動に成果が！？\nじゃあ騎士さんのこと、拉致しちゃうとか★　恋愛成就確定です♥", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 3, "", 620, 2, "今日の運勢は中吉！　おめかししたら運気も上昇？\n毛並がふわふわになるまでブラッシングしたわ♪　ふふ、完璧ね！", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 621, 2, "今日の運勢は小吉！　知らない場所に行くと新たな発見が！\n未知の場所……一人では恐ろしくて。騎士さま、どうかお力添えを", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 4, "", 622, 2, "今日の運勢は小吉！　ラッキーアイテムは鳥の羽根！\nだからって、私の羽を毟ろうとしないでくださ～いっ！", 0, "", 0, 2, 60007, 0);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 623, 0, "おみくじの結果はどうでしたか？\n新たに始まる一日が、あなたに\nとって良い日になりますように\nまた明日も遊びに来て下さいね♪", 190804, "カリン", 0, 3, 60007, 2);
INSERT INTO `v1_34965a4ee47250df16fe8e87d036acd4eb847ec77c29dde6bf9ba39abe3562d0` VALUES (0, 0, "", 624, 0, "おみくじは楽しんで頂けましたか？\nあなたの新たなる年が\n素晴らしいものになるよう、\n心からお祈りいたします", 190804, "カリン", 5, 3, 60007, 3);
